import AppKit
import ImageIO
import UniformTypeIdentifiers

public struct ClipClassifier: Sendable {
    public static let defaultMaxImageBytes = 40 * 1024 * 1024
    public static let defaultMaxTextBytes = 5 * 1024 * 1024
    public static let defaultMaxImagePixels = 50_000_000
    private static let rawImageAllowance = 4

    // Marker types from nspasteboard.org that password managers and automation tools add to private copies.
    static let skippedMarkerTypes: Set<String> = [
        "org.nspasteboard.ConcealedType", "org.nspasteboard.TransientType", "org.nspasteboard.AutoGeneratedType",
        "com.agilebits.onepassword", "de.petermaurer.TransientPasteboardType", "com.typeit4me.clipping",
        "Pasteboard generator type",
    ]
    private static let linkSchemes: Set<String> = ["http", "https", "ftp"]

    public let ignoredBundleIDs: Set<String>
    public let maxImageBytes: Int
    public let maxTextBytes: Int
    public let maxImagePixels: Int

    public init(
        ignoredBundleIDs: Set<String>,
        maxImageBytes: Int = defaultMaxImageBytes,
        maxTextBytes: Int = defaultMaxTextBytes,
        maxImagePixels: Int = defaultMaxImagePixels
    ) {
        self.ignoredBundleIDs = ignoredBundleIDs
        self.maxImageBytes = maxImageBytes
        self.maxTextBytes = maxTextBytes
        self.maxImagePixels = maxImagePixels
    }

    public func classify(_ snapshot: PasteboardSnapshot, source: ClipSource?) -> ClipCandidate? {
        guard !snapshot.types.isEmpty, !isPrivate(snapshot, source: source) else { return nil }
        if !snapshot.fileURLs.isEmpty {
            return ClipCandidate(kind: .file, text: snapshot.fileURLs.map(\.path).joined(separator: "\n"), source: source)
        }
        let text = snapshot.string ?? snapshot.urlString
        let hasText = !PasteboardSnapshot.isBlank(text)
        if let data = snapshot.imageData, !hasText || PasteboardSnapshot.imageComesFirst(snapshot.types),
           data.count <= maxImageBytes * Self.rawImageAllowance,
           let image = ImageEncoding.payload(from: data, maxPixels: maxImagePixels), image.png.count <= maxImageBytes {
            return ClipCandidate(kind: .image, text: "", image: image, source: source)
        }
        guard let text, hasText, text.utf8.count <= maxTextBytes else { return nil }
        let trimmed = text.trimmingCharacters(in: .whitespacesAndNewlines)
        if Self.isLink(trimmed) {
            return ClipCandidate(kind: .link, text: trimmed, source: source)
        }
        let rtf = snapshot.rtf.flatMap { $0.count <= maxTextBytes ? $0 : nil }
        return ClipCandidate(kind: .text, text: text, rtf: rtf, source: source)
    }

    static func isLink(_ text: String) -> Bool {
        guard !text.contains(where: \.isWhitespace), let url = URL(string: text),
              let scheme = url.scheme?.lowercased(), linkSchemes.contains(scheme) else { return false }
        return !(url.host ?? "").isEmpty
    }

    private func isPrivate(_ snapshot: PasteboardSnapshot, source: ClipSource?) -> Bool {
        if let bundleID = source?.bundleID, ignoredBundleIDs.contains(bundleID) {
            return true
        }
        return snapshot.types.contains { Self.skippedMarkerTypes.contains($0) }
    }

}

enum ImageEncoding {
    private static let pngSignature: [UInt8] = [0x89, 0x50, 0x4E, 0x47]

    static func payload(from data: Data, maxPixels: Int) -> ImagePayload? {
        guard let source = CGImageSourceCreateWithData(data as CFData, nil),
              let properties = CGImageSourceCopyPropertiesAtIndex(source, 0, nil) as? [CFString: Any],
              let width = properties[kCGImagePropertyPixelWidth] as? Int,
              let height = properties[kCGImagePropertyPixelHeight] as? Int,
              width > 0, height > 0, width <= maxPixels / height,
              let image = CGImageSourceCreateImageAtIndex(source, 0, nil), image.width > 0, image.height > 0
        else { return nil }
        let png = data.starts(with: pngSignature) ? data : encode(image, as: .png)
        return png.map { ImagePayload(png: $0, width: image.width, height: image.height) }
    }

    static func encode(_ image: CGImage, as type: UTType) -> Data? {
        let output = NSMutableData()
        guard let destination = CGImageDestinationCreateWithData(output, type.identifier as CFString, 1, nil) else { return nil }
        CGImageDestinationAddImage(destination, image, nil)
        return CGImageDestinationFinalize(destination) ? output as Data : nil
    }

    static func tiff(fromPNG data: Data) -> Data? {
        guard let source = CGImageSourceCreateWithData(data as CFData, nil),
              let image = CGImageSourceCreateImageAtIndex(source, 0, nil) else { return nil }
        return encode(image, as: .tiff)
    }
}
